local M = {}

local TAG = EM.MODULE.OVERSEAS .. "login"
local OFFICIAL_VENDOR_NAME = 'OFFICIAL'
local login_history = E.LazyKeyStore:New('QOOKKA_GAME_LOGIN_HISTORY', false, true, false)
local auto_login_mark = E.LazyKeyStore:New('QOOKKA_GAME_AUTO_LOGIN_MARK', false, false, false)
local LAST_LOGIN_SUCC_VENDOR = E.SPKeyStore:New('com.ejoy.sdk.lua', "LAST_LOGIN_SUCC_VENDOR")
local create_new_account_callback, bind_agst_callback -- 缓存gangplank中返回的回调
local login_callback
local login_resp_body
local is_webview_open = false
local is_handling_realm = false
local is_from_login = false
local login_webview_option

-- 只判断依赖外部三方应用登录的，系统登录或应用三方sdk集成登录的不作判断
local THIRDPARTY_APP = {
    ANDROID = {
        --LINE = "jp.naver.line.android",
        GOOGLE_PLAY = "com.google.android.play.games",
    },
    IOS = {
        --LINE = "lineauth2",
    }
}

local function need_sort_login_list()
    local sdk_infos = UNI.get_sdk_infos()
    local vendor_info = sdk_infos[OFFICIAL_VENDOR_NAME]
    if vendor_info and vendor_info.meta and vendor_info.meta.sort_login_list ~= nil then
        return vendor_info.meta.sort_login_list
    end
    return true
end

-- ft1与ft2交集
local function filter_table(ft1, ft2, accept_func)
    local k = 1
    while k <= #ft1 do
        local keep = false
        for i = 1, #ft2 do
            if accept_func(ft1[k], ft2[i]) then
                keep = true
                break
            end
        end
        if keep then
            k = k + 1
        else
            table.remove(ft1, k)
        end
    end
end

local inner_available_login_list = function()
    -- 从native获取可用登录方式
    local available_login_list = {}
    local login_vendors = EV.get_native_vendors(EV.ABILITY.ACCOUNT)
    E.LOG.debug(TAG, login_vendors or {})

    -- 获取历史登录方式
    local lh = UTILS.deepcopy(login_history:get()) or {}
    E.LOG.debug(TAG, lh or {})

    -- 获取登录方式配置列表
    local login_config = UTILS.deepcopy(EC.get('login'))
    E.LOG.debug(TAG, login_config or {})

    if login_config and next(login_config) then
        if (need_sort_login_list() == true) then
            -- 优先按操作历史记录排序, 可配置
            for j = 1, #lh do
                for i = #login_config, 1, -1 do
                    local tab = login_config[i]

                    if lh[j] == tab.type then
                        table.insert(available_login_list, tab)
                        table.remove(login_config, i)
                        break
                    end
                end
            end
        end

        for i = 1, #login_config do
            table.insert(available_login_list, login_config[i])
        end

        -- 对已经排序的总表按当前配置支持的登录方式过滤
        filter_table(available_login_list, login_vendors, function(available_item, login_item)
            return available_item.type == login_item
        end)

        local last_vendor = LAST_LOGIN_SUCC_VENDOR:get()
        if last_vendor and string.len(last_vendor) > 0 then
            for _, login_item in pairs(available_login_list) do
                if login_item.type == last_vendor then
                    login_item.last_login = true
                    break
                end
            end
        end

        local pga_login_type = 'PGA_LOGIN'
        if EV.has_vendor(pga_login_type) then
            for _, login_item in pairs(available_login_list) do
                if login_item.type == pga_login_type then
                    local pga_login = EV.get(pga_login_type)
                    local pga_can_continue_login = OFFICIAL.can_pga_autologin() or pga_login.show_continue_login()
                    login_item.can_continue_login = pga_can_continue_login
                    break
                end
            end
        end
        return available_login_list
    else
        return nil
    end
end

function M.available_login_list(cb)

    if not cb then
        return
    end

    -- 从native获取可用登录方式
    local available_login_list = inner_available_login_list();
    if available_login_list then
        PROTOCOL.succ_callback(cb, available_login_list)
    else
        PROTOCOL.fail_callback(cb, CONSTANTS.OFFICIAL_ERR_CODES.CODE_NOT_REQUEST_CONFIG, "获取配置失败")
    end
end

-- 特殊包体如DMM等，限制登录
local function need_channel_login()
    local init_args = E.CONFIG.get_config(E.CONFIG.KEY.INIT_ARGS)
    if type(init_args) == 'table' and next(init_args) and type(init_args.channel) == 'string' then
        local channel = string.upper(init_args.channel)
        if EV.get(channel) then
           return true,channel
        end
    end
    return false
end
local function can_channel_login()
    local succ, channel = need_channel_login()
    if succ == true then
        -- 从应用启动参数获取
        local init_args = E.CONFIG.get_config(E.CONFIG.KEY.INIT_ARGS)
        local channel_vendor = EV.get(channel)
        if channel_vendor and channel_vendor.check_args then
            return channel_vendor.check_args(init_args)
        end
    end
    return false
end

local function channel_login()
    local need_login, channel = need_channel_login()
    if need_login then
        E.LOG.debug(TAG, "need channel login:"..channel)
        local params = can_channel_login()

        local tips = '登录失败，请使用DMM GAME PLAYER重新启动游戏'
        if 'DMM_LOGIN' == channel then
            tips =  LANG.getString('dmm_login_err_msg', tips)
        end

        if params then
            E.LOG.debug(TAG, "can channel login")
            -- 开始自动登录渠道
            params.autologin = true
            params.login_from = 'local'
            M.login(channel,params,function(resp)
                local login_succ = type(resp) == 'table' and resp.succ == true and resp.body and resp.body.token ~= nil and resp.body.token ~= ''
                if login_succ then
                    --登录成功
                    E.LOG.debug(TAG, "channel login succ")
                    M.notify_login(true, resp.body.token)
                else
                    -- 不能登录到渠道，直接报错返回游戏失败,固定错即可，让游戏知道是不能用这种方式登录
                    E.LOG.debug(TAG, "channel login fail")
                    local err_code = ""

                    if type(resp) == 'table' and resp.succ == false and type (resp.body) == 'table' then
                        if resp.body.err_code then
                            err_code = '\ncode: ' .. tostring(resp.body.err_code)
                        end
                    end
                    E.Modal.open("",{ type = 'simple' , message = tips .. err_code}, function()
                        M.notify_login(false, CONSTANTS.OFFICIAL_ERR_CODES.CODE_LOGIN_NOT_SUPPORT, tips)
                    end)
                end
            end)
        else
            -- 不能登录到渠道，直接报错返回游戏失败
            E.LOG.debug(TAG, "channel login fail, missing params")

            E.Modal.open("",{ type = 'simple' , message = tips }, function()
                M.notify_login(false, CONSTANTS.OFFICIAL_ERR_CODES.CODE_LOGIN_NOT_SUPPORT, "Missing Login Parameters: " .. channel)
            end)
        end
        return true
    end
    return false
end

local function cache_login_history(type)
    -- 缓存方式点击的次序
    local cache_lh = login_history:get() or {}
    local lh = { type }

    for i = 0, #cache_lh do
        if (type ~= cache_lh[i]) then
            table.insert(lh, cache_lh[i])
        end
    end

    login_history:set(lh)
end

local function login(login_type, cb, pass_ext)
    E.log(TAG .. " login type=" .. tostring(login_type))
    pass_ext = pass_ext or {}
    cache_login_history(login_type)

    create_new_account_callback = nil
    bind_agst_callback = nil
    login_callback = cb
    login_resp_body = nil

    -- 只有通过这个函数进来的才需要考虑回调h5
    -- 手动登录，在登录页关闭前 --> h5回调
    -- 手动登录, 但被其他页面（如协议，实名）等被动关闭 --> 直接回调
    -- 自动登录不走这里
    is_from_login = true

    local gangplank = require 'ejoysdk_lua.ejoysdk_gangplank'
    local ext = {
        override_acquire_listener = function(succ, ...)
            local login_from = pass_ext.login_from or 'h5'
            E.LOG.debug(TAG,"type="..type(login_callback))
            local should_interrupt = (login_from == 'local' and type(login_callback) == 'function') -- local 表示都是无界面的本地登录调用，如自动登录（PGS,DDM等），主要针对想函数回调login_callback的情况
                    or (login_from == 'h5' and (is_webview_open or (is_from_login == true and E.WebView.is_opened()))) -- is_open的h5不一定是登录页， 有可能是协议啥的,但因为用户中心绑定（如引继码）也会用到这里的登录，还需要打开
            is_from_login = false -- 离开登录页
            if succ then
                E.LOG.debug(TAG,"acquire, login succ")
                local t, body = ...
                login_resp_body = body
                -- 回调给h5，h5此时需要关闭
                if should_interrupt then
                    -- 业务复杂后来到这里时不一定都是登录页，判断login_from的意义仅用于判断不是自动登录
                    PROTOCOL.succ_callback(login_callback, { token = t })
                else
                    M.notify_login(succ, t)
                end
            else
                E.LOG.debug(TAG,"acquire, login failed")
                OFFICIAL.reset_last_official_login()

                local code, message, outsource = ...
                if (code == USER.USER_CENTER_ERROR_CODES.ERR_AGST_ROLE_BIND_CONFLICT) then

                    local callback_funcs = function(cb2)
                        cb2 = cb2 or function()  end
                        if login_type == 'PGA_LOGIN'
                                and outsource and next(outsource)
                                and outsource.ext_info and next(outsource.ext_info)
                                and outsource.ext_info.ptoken then
                            -- 绑定需要重新获取一次ptoken
                            local pga_login = EV.get(login_type) or {}
                            pga_login.get_auth_code(function(succ2, ...)
                                local auth_data = ...
                                if succ2 and auth_data and next(auth_data) and auth_data.auth_code and '' ~= auth_data.auth_code then
                                    -- 替换auth_code
                                    local auth_code = auth_data.auth_code
                                    local ptoken = JSON.decode(outsource.ext_info.ptoken)
                                    ptoken.code = auth_code
                                    cb2(JSON.encode(ptoken))
                                else
                                    -- 取默认操作,会失败
                                    cb2()
                                end
                            end,true)
                        else
                            cb2()
                        end
                    end
                    create_new_account_callback = function()
                        callback_funcs(outsource.create_new_account)
                    end
                    bind_agst_callback  = function()
                        callback_funcs(outsource.bind_agst)
                    end

                    is_from_login = true -- 绑定同样也是在登录页, 再次打开
                end

                if code == 428 then
                    -- 实名GP不通过，需要回到登录页,不通知
                    if E.WebView.is_opened() then
                        E.WebView.close() -- 目前只允许打开一个页面，必须先提前关闭
                    end
                    EG.acquire_token();
                    return
                end

                if should_interrupt then
                    PROTOCOL.fail_callback(login_callback, code, message, outsource.ext_info)
                else
                    M.notify_login(succ, code, message)
                end
            end
        end,
        pass_ext = pass_ext or {}
    }
    gangplank._acquire_token_global(login_type, nil, ext)
end

function M.create_new_guest(cb)
    -- 清除转正标记
    OFFICIAL.clear_agst_official_sign()
    login(AGST_VENDOR_NAME, cb)
end

-- 兼容 M.login(type,cb)
function M.login(login_type, ext, cb)
    if type(ext) == 'function' or not (ext and cb) then
        --旧方法调用
        cb = ext
        --判断本地游客转正标记，已转正就返回
        if AGST_VENDOR_NAME == login_type and OFFICIAL.has_marked_agst_official() then
            PROTOCOL.fail_callback(cb, CONSTANTS.OFFICIAL_ERR_CODES.CODE_AGST_HAS_BOUND, "游客已转正")
            return
        end

        login(login_type, cb)
    elseif type(ext) == 'table' then
        login(login_type, cb, ext)
    end

    -- 登录方式调用打点
    EQL.commit_action_main("al_login_invoke", login_type)
end

-- 聚合页调用的挑战登录
-- param:
--- challenge_info: 玩家填完挑战页面后，获取到的挑战信息
--- cb: 登录回调，挑战成功返回登录成功结果，挑战失败返回错误码500015
function M.login_with_challenge_info(challenge_info, cb)
    login_callback = cb
    ECM.login_with_challenge_info(challenge_info)
end

-- 通知回游戏acquire
function M.notify_login(succ, ...)
    if (EG.get_listener() and EG.get_listener().acquire_listener) then
        if succ then
            local token = ...
            EG.get_listener().acquire_listener(succ, token, login_resp_body)
            EQL.commit_action_succ_main("al_h5_login_end")
        else
            local code, msg = ...
            EG.get_listener().acquire_listener(succ, code, msg)
            EQL.commit_action_fail_main("al_h5_login_end", nil, code, msg)
        end
    end
end

function M.ignore_bind_agst(cb)
    if create_new_account_callback then
        login_callback = cb
        create_new_account_callback()
        create_new_account_callback = nil
    end
end

function M.bind_agst(cb)
    if bind_agst_callback then
        login_callback = cb
        bind_agst_callback()
        bind_agst_callback = nil
    end

end

local function auto_login_support(type)
    if not type or '' == type then
        return false
    end

    local flag = nil
    if _ejoysdk.os() == 'android' then
        if 'GOOGLE' == type then
            -- google需要判断service
            local is_support = UNI.sync_call(type, 'SYNC_IS_SUPPORT_PLAY_SERVICE', {})
            return (is_support and is_support.supported == true) or false
        end
        flag = THIRDPARTY_APP.ANDROID[type]
    elseif _ejoysdk.os() == 'ios' then
        flag = THIRDPARTY_APP.IOS[type]
    end

    if flag then
        return E.Sysinfo.is_app_install(flag)
    else
        return true
    end
end

-- 如果已经接入PGS则优先检查PGS是否已经有账号，有的话自动进入
local function try_pgs_autologin(cb)
    local login_type = 'PGA_LOGIN'
    if (not EV.has_vendor(login_type) or need_channel_login()) then
        -- 如果没接pgs，或需要渠道登录的，都不需要走PGS
        cb(false)
        return
    end

    local pga_login = EV.get(login_type) or {}
    if pga_login.get_auth_code then
        pga_login.get_auth_code(function(succ, ...)
            if succ then
                M.login(login_type, { login_from = 'local', register_disabled = true }, function(resp)
                    -- 来到这里肯定就已经失败了，成功会直接通知游戏
                    local login_succ = resp and resp.succ == true and resp.body and resp.body.token ~= nil and resp.body.token ~= ''
                    if login_succ then
                        -- 老用户
                        M.notify_login(resp.succ, resp.body.token)
                        --else
                        -- 新的首次会失败
                    end
                    cb(login_succ)
                end)
            else
                cb(false)
            end
        end)
    else
        cb(false);
    end
end

local function try_auto_login_with_config(cb)
    -- 一些地区会有直接自动登录的需求，如日本
    local auto_login_config = UTILS.deepcopy(EC.get('autoLogin'))
    if auto_login_config and next(auto_login_config) then
        local login_vendors = EV.get_native_vendors(EV.ABILITY.ACCOUNT)
        filter_table(auto_login_config, login_vendors, function(auto_item, login_item)
            return auto_item.type == login_item and 'AIRLINE' ~= auto_item.type and 'TWITTER_LOGIN' ~= auto_item.type  -- AIRLINE,TWITTER不适应于这种自动登录
        end)

        if auto_login_config and next(auto_login_config) then
            for _, login_config in ipairs(auto_login_config) do
                local login_type = login_config.type
                if auto_login_support(login_type) then
                    M.login(login_type, { login_from = 'local' }, function(resp)
                        -- 来到这里肯定就已经失败了，成功会直接通知游戏
                        if resp and resp.succ and resp.body and resp.body.token then
                            M.notify_login(resp.succ, resp.body.token)
                        end
                        cb(resp and resp.succ == true)
                    end)
                    return
                end
            end
        end
    end
    cb(false)
end

function M.try_auto_login(cb)
    if not auto_login_mark:get() then
        auto_login_mark:set(1)
        try_pgs_autologin(function(succ)
            if not succ then
                try_auto_login_with_config(cb)
            end
        end)
    else
        cb(false)
    end
end

function M.get_agst_token(cb)
    local AGST_TOKEN = require 'ejoysdk_lua.user_center.agst_token_manager'
    AGST_TOKEN.get_token(function(token)
        PROTOCOL.succ_callback(cb, { agst_token = token })
    end)
end

function M.handle_realname(user_data, cb)
    cb = cb or {}
    -- 登录拦截统一处理了，实名制和儿童年龄的检查都交给H5来处理，做成通用的拦截方案
    if user_data and user_data.frontParam then
        local realname_handler = require 'ejoysdk_lua.realname.ejoysdk_popup_handler'
        local scene = realname_handler.SCENE_TYPE.SCENE_AFTER_LOGIN
        local can_close = true--user_data.frontParam.realName.forceVerify == false

        local callback = function(status)
            is_handling_realm = false
            cb(status == realname_handler.USERCENTER_REALNAME_STATUS.STATUS_SUCCESS, status)
        end

        local page_url = OFFICIAL.get_api_url('login_intercept')

        if E.WebView.is_opened() then
            is_handling_realm = true -- 标记一下，防止关闭登录页时登录结果直接就出去了

            E.WebView.close() -- 目前只允许打开一个页面，必须先提前关闭
        end
        -- 自动登录也会到这里
        realname_handler.handle_overseas_realname_page(page_url, scene, can_close, { frontParam = user_data.frontParam }, callback)
    else
        cb(true, user_data)
    end
end

function M.open_login_webview(preferred, fallback)

    -- 渠道登录优先
    if channel_login() == true then
        return
    end

    local close_callback = function()
        is_webview_open = false
        is_from_login = false

        --没登录成功，则返回登录取消
        if (not is_handling_realm and not (EG.user_info() and EG.user_info().token and string.len(EG.user_info().token) > 0)) then
            EG.logout(true)
            M.notify_login(false, CONSTANTS.OFFICIAL_ERR_CODES.CODE_LOGIN_CANCEL, "取消登录")
        end
    end

    local option = {
        startupData = {
            area = E.CONFIG.get_config('district'),
            language = E.CONFIG.get_config('lang'):lower(),
            publish_area = E.CONFIG.get_config(E.CONFIG.KEY.PUBLISH_AREA) or '',
            pkg_info = E.get_pkg_info(),
            aegis_data = AEGIS_DATA.get_encrypt_data(),
            available_login_list = inner_available_login_list()
        },
        transparent = true
    }

    fallback = fallback or { url = '', host = '' }

    local login_option = { compactMode = true, use_fragment = true, hide_close_btn = true, use_cutout = true, fallback_url = fallback.url }
    if login_webview_option and type(login_webview_option) == 'table' then
        for k,v in pairs(login_webview_option) do
            login_option[k] = v
        end
    end

    E.WebView.open(
            preferred.url,
            {
                [preferred.host] = option,
                [fallback.host] = option
            },
            login_option, nil, close_callback)

    is_webview_open = true

    -- 显示手动登录页面
    EQL.commit_action_main("al_show_h5_login")
end

function M.inject_webview_options(_options)
    if _options then
        login_webview_option = _options
    end
end

return M
